'use strict';
const $=s=>document.querySelector(s);let products=[],filter='all',query='';const money=p=>Number(p.price.replace(/[^0-9.]/g,''));
function render(){const list=products.filter(p=>(filter==='all'||p.category===filter)&&`${p.name} ${p.code}`.toLowerCase().includes(query));$('#products').replaceChildren(...list.map(p=>{const b=document.createElement('button');b.className='product';b.setAttribute('aria-label',`${p.name}, from ${p.price}. View product`);const box=document.createElement('span');box.className='product-image';const img=document.createElement('img');img.src=p.image;img.alt=p.name;img.loading='lazy';img.width=500;img.height=500;box.append(img);b.append(box);for(const [cls,value] of [['code',p.code],['name',p.name],['price',`FROM ${p.price}`]]){const el=document.createElement('span');el.className=cls;el.textContent=value;b.append(el)}b.addEventListener('click',()=>openProduct(p));return b}));$('#empty').hidden=list.length>0;$('#count').textContent=`${String(list.length).padStart(2,'0')} PIECES / ${filter.toUpperCase()}`;document.querySelectorAll('.categories button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.filter===filter)))}
function openProduct(p){$('#detail-img').src=p.image;$('#detail-img').alt=p.name;$('#detail-title').textContent=p.name;$('#detail-code').textContent=`${p.code} / ${p.category.toUpperCase()}`;$('#detail-price').textContent=`FROM ${p.price} USD`;$('#buy').href=p.url;$('#detail').showModal()}
for(const d of document.querySelectorAll('dialog')){d.querySelector('.close').addEventListener('click',()=>d.close());d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close()}})}
$('#menu-toggle').addEventListener('click',()=>{$('#menu').showModal();$('#menu-toggle').setAttribute('aria-expanded','true')});$('#menu').addEventListener('close',()=>$('#menu-toggle').setAttribute('aria-expanded','false'));
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{filter=b.dataset.filter;render();$('#menu').close();window.scrollTo({top:0,behavior:'instant'})}));
$('#search-toggle').addEventListener('click',()=>{$('#search-panel').hidden=!$('#search-panel').hidden;if(!$('#search-panel').hidden)$('#search').focus()});$('#search').addEventListener('input',e=>{query=e.target.value.trim().toLowerCase();render()});$('#clear-search').addEventListener('click',()=>{$('#search').value='';query='';render();$('#search').focus()});$('#about').addEventListener('click',()=>$('#about-dialog').showModal());$('#year').textContent=new Date().getFullYear();
fetch('products.json').then(r=>{if(!r.ok)throw Error('Catalog unavailable');return r.json()}).then(data=>{products=data;render()}).catch(()=>{$('#empty').hidden=false;$('#empty').textContent='The collection could not load. Please refresh, or visit the original shop below.'});
